// Single source of commercial rules: frontend/product-catalog.js (+ frontend/fragrance.js).
// This script writes the server copy. `--check` fails if the server copy is out of date.
//   node scripts/sync-commercial-rules.mjs          -> regenerate server/commercial-rules.generated.mjs
//   node scripts/sync-commercial-rules.mjs --check  -> exit 1 when the generated file differs
import { createRequire } from 'node:module';
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(import.meta.url);
const catalog = require(path.join(root, 'frontend/product-catalog.js'));
const fragrance = require(path.join(root, 'frontend/fragrance.js'));
const summary = catalog.commercialSummary();
const rules = {
  products: summary.products,
  fragrances: fragrance.OPTIONS.map(item => item.id),
  minimumWhite: summary.minimumWhite,
  minimumColored: summary.minimumColored,
  cartons: summary.cartons,
  unprintedFragrance: summary.unprintedFragrance,
};
const text = '// GENERATED by scripts/sync-commercial-rules.mjs from frontend/product-catalog.js and frontend/fragrance.js.\n'
  + '// Do not edit by hand; change the catalog and run the script. tests/commercial-rules-sync.test.cjs checks this file.\n'
  + 'export const COMMERCIAL_RULES = Object.freeze(' + JSON.stringify(rules, null, 2) + ');\n';
const target = path.join(root, 'server/commercial-rules.generated.mjs');
if (process.argv.includes('--check')) {
  const current = existsSync(target) ? readFileSync(target, 'utf8') : '';
  if (current !== text) { console.error('[commercial rules] FAIL: server/commercial-rules.generated.mjs is out of date. Run node scripts/sync-commercial-rules.mjs'); process.exit(1); }
  console.log('[commercial rules] PASS server copy matches frontend/product-catalog.js');
} else {
  writeFileSync(target, text);
  console.log('[commercial rules] wrote server/commercial-rules.generated.mjs');
}
